[
  {
    "statement": "The evidence on the effectiveness of creating or retaining habitat corridors for conserving peatland vegetation is extremely limited.",
    "citations": []
  },
  {
    "statement": "Only one study was found that evaluated the effects on peatland vegetation of retaining or creating habitat corridors in farmed areas.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "A single study was conducted in a tropical peat swamp forest in Indonesia.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "The Indonesian study found that a peat swamp forest corridor contained 5,819 trees per hectare.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "The peat swamp forest corridor in the study included 331 large trees, 1,360 saplings, and 4,128 seedlings per hectare.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "A study in a tropical peat swamp forest in Indonesia recorded 18-29 tree species in a habitat corridor.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "The number of tree species recorded in the peat swamp forest corridor depended on the size class.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of retaining or creating habitat corridors in areas of energy production or mining for peatland vegetation conservation.",
